    'already blocked' => 'از قبل مسدود',
    'asked for an admin role' => 'نقش مدیر خواست',
    'role that does not exist' => 'نقشی که وجود ندارد',
    'filled the trap field' => 'فیلد تله را پر کرد',
    'forged page stamp' => 'مهر صفحهٔ جعلی',
